import React from 'react';

// This component will display process fields.
// Editing functionality will be added later and will involve lifting state.
const ProcessDetails = ({ processData }) => {
  // processData is now directly from props, assumed to be populated by the parent.

  // Simple display of list items, ensuring items is an array
  const renderList = (items, fieldName) => (
    <ul>
      {Array.isArray(items) && items.length > 0 ? (
        items.map((item, index) => (
          <li key={`${fieldName}-${index}`}>{item || 'N/A'}</li>
        ))
      ) : (
        <li>No {fieldName} specified.</li>
      )}
    </ul>
  );

  const sectionStyle = {
    marginBottom: 'calc(var(--spacing-unit, 16px) * 1.5)',
  };

  const labelStyle = {
    fontWeight: 'bold',
    display: 'block',
    marginBottom: 'calc(var(--spacing-unit, 16px) / 4)',
    color: 'var(--primary-color)'
  };

  const textStyle = {
    fontSize: '0.95em',
    lineHeight: '1.6',
    color: '#333'
  };

  if (!processData) {
    return <p>No process details available.</p>;
  }

  return (
    // The maxHeight style was removed to allow ProcessVisualization to control scroll on its child container
    <div> 
      <h4>Extracted Process Details</h4>

      <div style={sectionStyle}>
        <label style={labelStyle}>General Description:</label>
        <p style={textStyle}>{processData.general_description || 'Not specified.'}</p>
      </div>

      <div style={sectionStyle}>
        <label style={labelStyle}>Process Steps:</label>
        {renderList(processData.process_steps, 'steps')}
      </div>

      <div style={sectionStyle}>
        <label style={labelStyle}>Scope:</label>
        <p style={textStyle}>{processData.scope || 'Not specified.'}</p>
      </div>

      <div style={sectionStyle}>
        <label style={labelStyle}>Inputs:</label>
        {renderList(processData.inputs, 'inputs')}
      </div>

      <div style={sectionStyle}>
        <label style={labelStyle}>Outputs:</label>
        {renderList(processData.outputs, 'outputs')}
      </div>

      <div style={sectionStyle}>
        <label style={labelStyle}>KPIs:</label>
        {renderList(processData.kpis, 'KPIs')}
      </div>

      <div style={sectionStyle}>
        <label style={labelStyle}>Roles & Responsibilities:</label>
        {renderList(processData.roles_responsibilities, 'roles & responsibilities')}
      </div>

      <div style={sectionStyle}>
        <label style={labelStyle}>Exceptions & Special Cases:</label>
        {renderList(processData.exceptions_special_cases, 'exceptions & special cases')}
      </div>

    </div>
  );
};

export default ProcessDetails;
